"use client"

import React, { useId, useState } from "react"

type LoginData = {
  identifier: string
  password: string
}

type Props = {
  defaultIdentifier?: string
  loading?: boolean
  errorMessage?: string
  onSubmit?: (data: LoginData) => Promise<void> | void
}

export default function LoginForm({ defaultIdentifier = "", loading = false, errorMessage = "", onSubmit }: Props) {
  const idPrefix = useId()
  const [identifier, setIdentifier] = useState(defaultIdentifier)
  const [password, setPassword] = useState("")
  const [localLoading, setLocalLoading] = useState(false)
  const [serverError, setServerError] = useState<string | null>(errorMessage || null)
  const [showPassword, setShowPassword] = useState(false)

  const submitting = loading || localLoading

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    setServerError(null)
    setLocalLoading(true)
    try {
      if (onSubmit) {
        await onSubmit({ identifier, password })
      }
    } catch (err: any) {
      setServerError(err?.message || "ログインに失敗しました。")
    } finally {
      setLocalLoading(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} aria-live="polite" noValidate>
      <div>
        <label htmlFor={`${idPrefix}-identifier`}>メールアドレス または ユーザー名</label>
        <input
          id={`${idPrefix}-identifier`}
          name="identifier"
          type="text"
          value={identifier}
          onChange={(e) => setIdentifier(e.target.value)}
          required
          autoComplete="username"
        />
      </div>

      <div>
        <label htmlFor={`${idPrefix}-password`}>パスワード</label>
        <input
          id={`${idPrefix}-password`}
          name="password"
          type={showPassword ? "text" : "password"}
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          autoComplete="current-password"
        />
        <button type="button" onClick={() => setShowPassword((s) => !s)} aria-pressed={showPassword}>
          {showPassword ? "非表示" : "表示"}
        </button>
      </div>

      {serverError && (
        <div role="alert" aria-live="assertive">
          {serverError}
        </div>
      )}

      <div>
        <button type="submit" disabled={submitting}>
          {submitting ? "送信中..." : "ログイン"}
        </button>
      </div>
    </form>
  )
}

"use client"

import React from "react"
import { useRouter } from "next/navigation"
import LoginForm from "../../components/LoginForm"
import styles from "./login.module.css"
import { login } from "../../lib/auth"

type FormData = {
  identifier: string
  password: string
}

export default function LoginPage() {
  const router = useRouter()

  async function handleSubmit(data: FormData) {
    try {
      const res = await login(data.identifier, data.password)
      if (res?.token) {
        // トークンの保存はバックエンド設計に従う（ここでは簡易扱い）
        localStorage.setItem("token", res.token)
        router.push("/dashboard")
      } else {
        throw new Error(res?.message || "ログインに失敗しました。")
      }
    } catch (err: any) {
      throw new Error(err?.message || "ネットワークエラーが発生しました。")
    }
  }

  return (
    <div className={styles.container}>
      <h1 className={styles.title}>ログイン</h1>
      <div className={styles.formWrap}>
        <LoginForm onSubmit={handleSubmit} />
      </div>
    </div>
  )
}

.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 16px;
}

.title {
  font-size: 1.5rem;
  margin-bottom: 16px;
}

.formWrap {
  width: 100%;
  max-width: 420px;
  background: #fff;
  border-radius: 8px;
  padding: 24px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.field {
  margin-bottom: 12px;
}

.label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
}

.input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #d0d7de;
  border-radius: 6px;
}

.button {
  width: 100%;
  padding: 10px 12px;
  background: #0b5fff;
  color: #fff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.error {
  color: #b00020;
  margin-bottom: 12px;
}

export type LoginResponse = {
  token?: string
  message?: string
}

export async function login(identifier: string, password: string): Promise<LoginResponse> {
  const res = await fetch("/api/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ identifier, password }),
  })

  const data = await res.json().catch(() => ({}))

  if (!res.ok) {
    throw new Error((data && data.message) || "認証に失敗しました。")
  }

  return data as LoginResponse
}

