"use client"

import React from "react"
import { useRouter } from "next/navigation"
import LoginForm from "../components/LoginForm"
import styles from "../pages/login/login.module.css"
import { login } from "../lib/auth"

type FormData = {
  identifier: string
  password: string
}

export default function LoginPage() {
  const router = useRouter()

  async function handleSubmit(data: FormData) {
    try {
      const res = await login(data.identifier, data.password)
      if (res?.token) {
        localStorage.setItem("token", res.token)
        router.push("/dashboard")
      } else {
        throw new Error(res?.message || "ログインに失敗しました。")
      }
    } catch (err: any) {
      // 上位でハンドリングされる想定のためここではthrowする
      throw new Error(err?.message || "ネットワークエラーが発生しました。")
    }
  }

  return (
    <div className={styles.container}>
      <div className={styles.centerCard}>
        <div className={styles.cardTop}>
          <div className={styles.headerIllustration} aria-hidden="true" />
          <div className={styles.cardTitle}>team sharing</div>
        </div>

        <div className={styles.cardBody}>
          <h1 className={styles.title}>ログイン</h1>
          <div className={styles.formWrap}>
            <LoginForm onSubmit={handleSubmit} />
          </div>

          <div className={styles.helpBox}>
            <div>まだアカウントをお持ちでないですか？</div>
            <div className={styles.helpSub}>アカウント登録はこちらです！</div>
          </div>
        </div>
      </div>
    </div>
  )
}

.container {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 16px;
  background: linear-gradient(180deg, #dbefff 0%, #c3ddff 100%);
}

.title {
  font-size: 1.75rem;
  margin: 0 0 12px 0;
  text-align: center;
  color: #071431;
  font-weight: 700;
}

.centerCard {
  width: 100%;
  max-width: 760px;
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(11,95,255,0.12);
  background: linear-gradient(180deg,#6fb1ff 0%,#86b9ff 100%);
}

.cardTop {
  padding: 28px 40px;
  background: linear-gradient(180deg, rgba(255,255,255,0.06), transparent 40%);
  position: relative;
}

.headerIllustration {
  width: 320px;
  height: 88px;
  margin: 0 auto 8px auto;
  border-radius: 12px;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.7), transparent 20%), radial-gradient(circle at 70% 30%, rgba(255,255,255,0.5), transparent 15%);
  opacity: 0.9;
}

.cardTitle {
  text-align: center;
  color: #ffffff;
  font-size: 22px;
  font-weight: 700;
  margin-top: 6px;
}

.cardBody {
  background: #ffffff;
  padding: 32px 40px 40px 40px;
}

.formWrap {
  width: 100%;
  max-width: 560px;
  margin: 0 auto 8px auto;
}

.form {
  display: flex;
  flex-direction: column;
}

.field {
  margin-bottom: 14px;
}

.label {
  display: block;
  margin-bottom: 8px;
  font-weight: 700;
  color: #0f172a;
}

.input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid #e6eefb;
  border-radius: 28px;
  font-size: 1rem;
  transition: box-shadow 0.12s ease, border-color 0.12s ease;
  background: #ffffff;
}

.input:focus {
  outline: none;
  border-color: #7fb5ff;
  box-shadow: 0 6px 20px rgba(11,95,255,0.12);
}

.toggleButton {
  padding: 10px 12px;
  background: #eef2ff;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  color: #0b5fff;
  cursor: pointer;
}

.button {
  width: 100%;
  padding: 14px 18px;
  background: linear-gradient(180deg,#f79b3b,#f36e2b);
  color: #fff;
  border: none;
  border-radius: 34px;
  cursor: pointer;
  font-weight: 800;
  font-size: 1.05rem;
}

.button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error {
  color: #b00020;
  margin-bottom: 12px;
  font-weight: 600;
}

.meta a { color: #0b5fff }

.fieldError {
  color: #b00020;
  margin-top: 6px;
  font-size: 0.875rem;
}

.helpBox {
  margin: 18px auto 0 auto;
  max-width: 560px;
  background: #d9e9ff;
  border-radius: 12px;
  padding: 14px 18px;
  text-align: center;
  color: #2b4f74;
}

.helpSub { margin-top: 6px }

